// RFC 4180 parser. Empty lines produce no record.
export function parseCsv(text: string): string[][] {
  const records: string[][] = [];
  let record: string[] = [];
  let field = "";
  let inQuotes = false;
  let fieldWasQuoted = false;
  let i = 0;

  const endField = () => {
    record.push(field);
    field = "";
    fieldWasQuoted = false;
  };
  const endRecord = () => {
    endField();
    const isEmptyLine = record.length === 1 && record[0] === "" && !lastFieldQuoted;
    if (!isEmptyLine) records.push(record);
    record = [];
  };
  let lastFieldQuoted = false;

  while (i < text.length) {
    const char = text[i];
    if (inQuotes) {
      if (char === '"' && text[i + 1] === '"') {
        field += '"';
        i += 2;
        continue;
      }
      if (char === '"') inQuotes = false;
      else field += char;
      i++;
      continue;
    }
    if (char === '"' && field === "" && !fieldWasQuoted) {
      inQuotes = true;
      fieldWasQuoted = true;
    } else if (char === ",") {
      endField();
    } else if (char === "\n" || (char === "\r" && text[i + 1] === "\n")) {
      lastFieldQuoted = fieldWasQuoted;
      endRecord();
      if (char === "\r") i++;
    } else {
      field += char;
    }
    i++;
  }

  if (field !== "" || fieldWasQuoted || record.length > 0) {
    lastFieldQuoted = fieldWasQuoted;
    endRecord();
  }
  return records;
}

// RFC 4180 parser. An empty line produces no record.
export function parseCsv(text: string): string[][] {
  const records: string[][] = [];
  let record: string[] = [];
  let field = "";
  let inQuotes = false;
  let fieldWasQuoted = false;

  const endField = () => {
    record.push(field);
    field = "";
    fieldWasQuoted = false;
  };
  const endRecord = () => {
    const isEmptyLine = record.length === 0 && field === "" && !fieldWasQuoted;
    endField();
    if (!isEmptyLine) records.push(record);
    record = [];
  };

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    if (inQuotes) {
      if (char !== '"') field += char;
      else if (text[i + 1] === '"') {
        field += '"';
        i++;
      } else inQuotes = false;
    } else if (char === '"' && field === "" && !fieldWasQuoted) {
      inQuotes = true;
      fieldWasQuoted = true;
    } else if (char === ",") {
      endField();
    } else if (char === "\n") {
      endRecord();
    } else if (char === "\r" && text[i + 1] === "\n") {
      endRecord();
      i++;
    } else {
      field += char;
    }
  }

  if (field !== "" || fieldWasQuoted || record.length > 0) endRecord();
  return records;
}

const AMOUNT = /^(-?)(\d+|\d{1,3}(?:,\d{3})+)(?:\.(\d{1,2}))?$/;

export function parseAmount(raw: string): number {
  const match = AMOUNT.exec(raw);
  if (!match) throw new Error(`invalid amount: ${JSON.stringify(raw)}`);
  const [, sign, integerPart, fraction = ""] = match;
  const cents = Number(integerPart.replaceAll(",", "") + fraction.padEnd(2, "0"));
  if (!Number.isSafeInteger(cents)) throw new Error(`amount too large: ${raw}`);
  return sign === "-" ? -cents : cents;
}

export function formatCents(cents: number): string {
  const sign = cents < 0 ? "-" : "";
  const abs = Math.abs(cents);
  const fraction = String(abs % 100).padStart(2, "0");
  return `${sign}${Math.floor(abs / 100)}.${fraction}`;
}

import { parseCsv } from "./csv";
import { parseAmount } from "./money";

export type Summary = {
  totals: Map<string, number>;
  skipped: number;
};

const COLUMNS = 4;

export function summarize(csvText: string): Summary {
  const rows = parseCsv(csvText).slice(1);
  const totals = new Map<string, number>();
  let skipped = 0;
  for (const row of rows) {
    if (row.length !== COLUMNS) {
      skipped++;
      continue;
    }
    const [, rawCategory, , rawAmount] = row;
    let amount: number;
    try {
      amount = parseAmount(rawAmount);
    } catch {
      skipped++;
      continue;
    }
    const category = rawCategory.trim();
    totals.set(category, (totals.get(category) ?? 0) + amount);
  }
  return { totals, skipped };
}

